function run_q5_dom_subject001_estimation_contrast()
repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');root=fullfile(repo,'results','q5_intrinsic_dom','cohort_specification','subject001');df=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1','subject001','subject001_nirs_data.mat');addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));D=load(df,'nirs_data');nch=D.nirs_data.nch;M=readtable(fullfile(fl,'nirs_spm_inputs','subject001','subject001_channel_metadata.csv'),'TextType','string');V=table();Slog=table();
for hb=["HbO","HbR"],sf=fullfile(root,char(hb),sprintf('SPM_indiv_%s.mat',hb));L=load(sf,'SPM_nirs');A=L.SPM_nirs;if ~isfield(A.nirs,'step')||~strcmpi(string(A.nirs.step),'estimation'),nirs_spm_estimation_batch_fixed(sf,df);L=load(sf,'SPM_nirs');A=L.SPM_nirs;end;B=double(A.nirs.beta);assert(isequal(size(B),[5 nch]));N=string(A.xX.name(:));tar=["LILEDOM","HILEDOM","LIHEDOM","HIHEDOM"];k=zeros(4,1);for i=1:4,k(i)=find(contains(N,tar(i)),1);end;c=zeros(5,1);c(k)=[-.5 .5 -.5 .5];rss=double(A.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;dof=double(A.xX.erdf);b=c'*B;se=sqrt(max((c'*double(A.xX.Bcov)*c).*(rss./dof),0));t=b./se;p=betainc(dof./(dof+t.^2),dof/2,.5);q=bh(p);R=table(repmat("subject001",nch,1),repmat(hb,nch,1),(1:nch)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),b(:),se(:),t(:),p(:),q(:),repmat(join(string(c'),' '),nch,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(R,fullfile(root,sprintf('subject001_%s_q5_high_intrinsic_minus_low_intrinsic_dom_channel_contrasts.csv',hb)));V=[V;table(hb,string(strjoin(cellstr(N(k))',' | ')),string(join(string(c'),' ')),size(B,1),size(B,2),dof,all(isfinite(B),'all'),all(isfinite(b)),'VariableNames',{'hemoglobin','located_task_regressors','implemented_contrast','n_beta_rows','n_channels','effective_df','beta_all_finite','contrast_all_finite'})];Slog=[Slog;table(hb,sum(p<.05),sum(q<.05),sum(b>0),sum(b<0),'VariableNames',{'hemoglobin','n_p_lt_005','n_q_bh61_lt_005','n_positive_beta','n_negative_beta'})];end
writetable(V,fullfile(root,'subject001_q5_dom_contrast_validation.csv'));writetable(Slog,fullfile(root,'subject001_q5_dom_contrast_summary.csv'));disp(V);disp(Slog);
end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));zv=zeros(size(pv));zv(o)=z;q(v)=zv;end
